html:
{%- set b = get_branding() -%}
<div dir="rtl" lang="ar" style="font-family: 'IBM Plex Sans Arabic', 'DejaVu Sans', Tahoma, sans-serif; color:#17201D; font-size:12px; line-height:1.7">
<p><b style="font-size:16px">{{ b.office_name }}</b></p>
<p>المشروع: <b>{{ frappe.db.get_value("Project", doc.project, "project_name") }}</b></p>
<h2>أمر تغيير: {{ doc.title }}</h2>
{% if doc.description %}<p>{{ doc.description }}</p>{% endif %}
<table style="width:100%;border-collapse:collapse">
<tr style="background:#E3F0EB"><th style="border:1px solid #C9CFC9;padding:6px;text-align:right">البند</th><th style="border:1px solid #C9CFC9;padding:6px">الكمية</th><th style="border:1px solid #C9CFC9;padding:6px">الإجمالي</th></tr>
{% for l in doc.lines %}<tr><td style="border:1px solid #C9CFC9;padding:6px">{{ l.section }} — {{ l.description or l.assembly or l.item or l.labor_type }}</td><td style="border:1px solid #C9CFC9;padding:6px;text-align:center" dir="ltr">{{ l.qty }}</td><td style="border:1px solid #C9CFC9;padding:6px;text-align:center" dir="ltr">{{ "{:,.2f}".format(l.line_total) }}</td></tr>{% endfor %}
</table>
<p style="font-size:14px"><b>قيمة أمر التغيير: <span dir="ltr">{{ "{:,.2f}".format(doc.cost_difference) }}</span> ج.م</b>{% if doc.cost_difference < 0 %} (خصم){% endif %}</p>
{% if doc.schedule_impact_days %}<p>تأثير على المدة: {{ doc.schedule_impact_days }} يوم</p>{% endif %}
</div>
